mapper.update:
UPDATE cultivation_diary_task AS t JOIN cultivation_diary AS d ON d.diary_id = t.diary_id JOIN cultivation_plan AS p ON p.plan_id = d.plan_id JOIN (
SELECT #{task.taskId} AS task_id, #{task.taskName} AS task_name, #{task.taskType} AS task_type, #{task.taskTime} AS task_time, #{task.taskStatus} AS task_status, #{task.taskContent,jdbcType=VARCHAR} AS task_content
) AS changes ON changes.task_id = t.task_id SET t.task_name = changes.task_name, t.task_type = changes.task_type, t.task_time = changes.task_time, t.task_status = changes.task_status, t.task_content = changes.task_content, t.updated_at = CURRENT_TIMESTAMP WHERE t.diary_id = #{diaryId} AND p.member_id = #{memberId} AND t.deleted_at IS NULL AND d.deleted_at IS NULL AND p.deleted_at IS NULL

mapper.delete:
DELETE t
FROM cultivation_diary_task AS t
JOIN cultivation_diary AS d ON d.diary_id = t.diary_id
JOIN cultivation_plan AS p ON p.plan_id = d.plan_id
WHERE t.diary_id = #{diaryId}
  AND p.member_id = #{memberId}
  AND d.deleted_at IS NULL
  AND p.deleted_at IS NULL
  AND t.task_id IN

    #{taskId}
